<script lang="ts">import{rows,text,numeric,compact,cost,priced,percent,number,type Row,type Query}from'../lib/api';import{tr}from'../lib/i18n';import Metrics from './Metrics.svelte';import Chart from './Chart.svelte';import Filters from './Filters.svelte';import Insights from './Insights.svelte';export let data:Row={};export let query:Query;export let onchange:(q:Query)=>void;let hover:Row|null=null;let share='tokens';$: buckets=rows(data.heatmap??data.activity?.rows);$: knownActivity=buckets.map(b=>number(b.tokens)).filter((n):n is number=>n!==null);$: peakActivity=knownActivity.length?Math.max(...knownActivity):null;$: maxActivity=Math.max(1,peakActivity??0);$: models=rows(data.models);$: total=models.reduce((n,m)=>n+(Number(m[share])||0),0);</script>
<Filters {query} models={data.models??[]} {onchange}/><Metrics summary={data.summary??{}} comparison={data.comparison??{}}/><Chart data={data.chart??[]} onselect={r=>onchange({...query,period:'custom',start:String(r.date??r.timestamp).slice(0,10),end:String(r.date??r.timestamp).slice(0,10),page:1})}/><section class="surface activity"><div class="row between"><h3>{tr('Token 活动')}</h3><span class="muted">{tr('单日峰值')} {compact(peakActivity)}</span></div><div class="heatmap">{#each buckets as b}<button aria-label={`${text(b.date??b.label)} ${numeric(b.tokens)} Token`} style:background={`var(--activity-${Number(b.tokens)>0?Math.max(1,Math.ceil(Number(b.tokens)/maxActivity*4)):0})`} onmouseenter={()=>hover=b} onmouseleave={()=>hover=null} onfocus={()=>hover=b} onblur={()=>hover=null} onclick={()=>onchange({...query,period:'custom',start:String(b.date).slice(0,10),end:String(b.date).slice(0,10),page:1})}></button>{/each}</div>{#if hover}<div class="row activity-detail"><strong>{text(hover.date??hover.label)}</strong><span>Token {numeric(hover.tokens)}</span><span>{tr('费用')} {cost(hover.usd)}</span><span>{tr('用户请求')} {numeric(hover.user_requests)}</span></div>{:else if !buckets.length}<p class="muted">{tr('暂无数据')}</p>{/if}</section>
<div class="trends-bottom"><section class="surface"><div class="row between"><h3>{tr('模型贡献')}</h3><select aria-label={tr('模型贡献')} bind:value={share}><option value="tokens">Token</option><option value="usd">{tr('费用')}</option><option value="user_requests">{tr('用户请求')}</option></select></div>{#each models as m}<div class="model-share"><div class="row between"><span>{text(m.model)}</span><span>{share==='usd'?priced(m,'usd'):numeric(m[share])} · {percent(total?Number(m[share])/total*100:null)}</span></div><div class="meter"><div style:width={`${total?(Number(m[share])||0)/total*100:0}%`} style:background="var(--tokens)"></div></div></div>{/each}{#if !models.length}<div class="empty small">{tr('暂无数据')}</div>{/if}</section><section class="surface"><h3>{tr('聊天排行')}</h3><div class="chat-ranking">{#each rows(data.chats).slice(0,query.page_size??50) as chat}<div class="ranking-row"><span title={text(chat.name??chat.session_title??chat.title)}>{text(chat.name??chat.session_title??chat.title)}</span><strong>{numeric(chat.tokens??chat.total_tokens)}</strong><small>{priced(chat,'usd')}</small></div>{/each}</div>{#if !rows(data.chats).length}<div class="empty small">{tr('暂无数据')}</div>{/if}{#if Number(data.chat_pages)>1}<div class="row"><button disabled={query.page<=1} onclick={()=>onchange({...query,page:query.page-1,page_size:5})}>{tr('上一页')}</button><span>{data.chat_page} / {data.chat_pages}</span><button disabled={query.page>=data.chat_pages} onclick={()=>onchange({...query,page:query.page+1,page_size:5})}>{tr('下一页')}</button></div>{/if}</section></div>
<Insights stats={data.insights?.stats??{}}/>
